import {expect, test} from '@playwright/test';
import {axe, THEMES, applyTheme, offline, settle} from './p6-helpers';
import {openAllSettingsGroups} from './settings-open';

/**
 * Session AV lane 2 (r3-plan, LEDGER #263; Structured's dyslexia-friendly font, without a font file): Settings → Appearance →
 * Customize → Font → "Reading-friendly" sets data-font="reading" on <html> at once and before the first paint of later pages
 * (public/theme-boot.js, regenerated by the lead from scripts/themes/build-themes.mjs), fetches no font file, and gives the
 * page a reading stack with wider letter, word and line spacing. At 390 and 1440 in Nebula, Light and Dark, axe-clean.
 */
const clean = async (page: import('@playwright/test').Page) => { const f = await axe(page, page.locator('main')); expect(f.filter(v => v.impact === 'serious' || v.impact === 'critical'), JSON.stringify(f)).toEqual([]); };

for (const theme of THEMES) test(`${theme}: the reading-friendly font, from the device's own fonts`, async ({page, isMobile}) => {
  await applyTheme(page, theme);
  await offline(page);
  if (!isMobile) await page.setViewportSize({width: 1440, height: 900});
  const fonts: string[] = [];
  page.on('request', r => { if (/\.(?:woff2?|ttf|otf)(?:\?|$)/.test(r.url())) fonts.push(r.url()); });
  // Session AV lane 2 (fixb3: on a computer Settings starts folded, deliberate): Open all, as a person does.
  await page.goto('/app/settings'); await settle(page); await openAllSettingsGroups(page);
  const group = page.getByRole('group', {name: 'Font'});
  await group.getByRole('radio', {name: 'Reading-friendly'}).check();
  await expect(page.locator('html')).toHaveAttribute('data-font', 'reading');
  await expect(page.getByText('Font: Reading-friendly. Saved on this device.')).toBeVisible();
  expect(await page.evaluate(() => (JSON.parse(localStorage.getItem('zigoals:ui-prefs:v1') ?? '{}') as {look?: {font?: string}}).look?.font)).toBe('reading');
  const style = await page.evaluate(() => { const s = getComputedStyle(document.body); return {family: s.fontFamily, letter: s.letterSpacing, line: s.lineHeight}; });
  expect(style.family).toMatch(/^"?Atkinson Hyperlegible"?, .*OpenDyslexic.*Verdana.*sans-serif$/);
  expect(style.letter).not.toBe('normal');
  await clean(page);
  // A later page has it before its first paint (the boot script), and no font file was fetched for it.
  await page.goto('/app/tasks'); await settle(page);
  await expect(page.locator('html')).toHaveAttribute('data-font', 'reading');
  expect(fonts).toEqual([]);
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth + 1)).toBe(true);
  // System again removes it.
  await page.goto('/app/settings'); await settle(page); await openAllSettingsGroups(page);
  await page.getByRole('group', {name: 'Font'}).getByRole('radio', {name: 'System'}).check();
  await expect(page.locator('html')).not.toHaveAttribute('data-font', /.+/);
});
